package ru.neverland.minttrade.contract;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.IOException;
import org.bukkit.configuration.*;import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.core.*;import ru.neverland.minttrade.integration.TreasuryFunding;
/** Schema 1 imports unchanged agreements; schema 2 adds acknowledged budget/audit intents. */
public final class SupplyJournal{
 public record Payment(UUID attempt,String protocol,TreasuryFunding.Terms terms){public Payment{Objects.requireNonNull(attempt);if(!Set.of("DIRECT","TREASURY").contains(protocol)||protocol.equals("TREASURY")!=(terms!=null))throw new IllegalArgumentException("Неверный протокол поставки");}}
 public record Image(Map<UUID,SupplyContract> contracts,Map<UUID,UUID> actors,Map<UUID,Payment> payments,Map<String,ReputationOutcome> reputation,List<AuditRecord> audit){
  public Image{contracts=Map.copyOf(contracts);actors=Map.copyOf(actors);payments=Map.copyOf(payments);reputation=Map.copyOf(reputation);audit=List.copyOf(audit);if(contracts.size()>5000||reputation.size()>10000||audit.size()>4096)throw new IllegalArgumentException("Архив договоров достиг предела");for(var entry:contracts.entrySet())if(!entry.getKey().equals(entry.getValue().terms().id()))throw new IllegalArgumentException("ID договора не совпадает");if(!contracts.keySet().containsAll(actors.keySet())||!contracts.keySet().containsAll(payments.keySet()))throw new IllegalArgumentException("Нет договора для финансового намерения");for(var c:contracts.values())if(c.attempt()!=null&&c.attempt().phase()==SupplyContract.Phase.DEBIT_READY&&!payments.containsKey(c.terms().id()))throw new IllegalArgumentException("Нет протокола подготовленного списания");for(var entry:payments.entrySet()){var c=contracts.get(entry.getKey());var payment=entry.getValue();if(c.attempt()==null||!c.attempt().id().equals(payment.attempt()))throw new IllegalArgumentException("Квитанция другой попытки поставки");var t=payment.terms();if(t!=null&&(!t.operation().equals(debit(payment.attempt()))||!t.town().equals(c.terms().buyer())||t.cents()!=c.terms().cents()||!t.source().equals("trade")||!t.actor().equals(new UUID(0,0))))throw new IllegalArgumentException("Бюджетное намерение не соответствует договору");}var ids=new HashSet<String>();for(var record:audit)if(!ids.add(record.id()))throw new IllegalArgumentException("Повтор квитанции журнала");}
  public static Image empty(){return new Image(Map.of(),Map.of(),Map.of(),Map.of(),List.of());}
 }
 private final Path file;private final AcknowledgedState<Image> data;
 public SupplyJournal(Path file){this.file=file;data=new AcknowledgedState<>(file,Image.empty(),SupplyJournal::encode,"nlt-trade-supply-journal");}
 public static UUID debit(UUID attempt){return EffectJournal.id("supply:"+attempt+":debit");}
 public Image image(){return data.get();}public boolean writable(){return data.writable();}public boolean busy(){return data.busy();}public CompletionStage<Void> close(){return data.prepareClose();}
 public void load()throws Exception{
  if(SuiteState.held())throw new IllegalStateException("Договоры загружаются вне общего guard");if(!Files.exists(file)){data.loaded(Image.empty());return;}if(Files.size(file)>32L*1024*1024)throw new IOException("Журнал договоров больше 32 МиБ");var y=new YamlConfiguration();y.load(file.toFile());int schema=y.getInt("schema");if(schema!=1&&schema!=2)throw new IOException("Неизвестная схема договоров");var root=y.getConfigurationSection("contracts");if(root==null||root.getKeys(false).size()>5000)throw new IOException("Нет договоров или превышен предел архива");var contracts=new LinkedHashMap<UUID,SupplyContract>();for(String key:root.getKeys(false)){UUID id=UUID.fromString(key);contracts.put(id,SupplyRepository.read(id,root.getConfigurationSection(key)));}
  var actors=new HashMap<UUID,UUID>();var a=y.getConfigurationSection("actors");if(a!=null)for(String key:a.getKeys(false))actors.put(UUID.fromString(key),UUID.fromString(a.getString(key)));
  var payments=new HashMap<UUID,Payment>();var p=y.getConfigurationSection("payments");if(p!=null)for(String key:p.getKeys(false)){var s=p.getConfigurationSection(key);UUID attempt=UUID.fromString(s.getString("attempt"));String protocol=s.getString("protocol");TreasuryFunding.Terms terms=null;if(protocol.equals("TREASURY"))terms=new TreasuryFunding.Terms(UUID.fromString(s.getString("operation")),UUID.fromString(s.getString("town")),UUID.fromString(s.getString("actor")),integer(s,"cents"),s.getString("category"),s.getString("source"),s.getString("reason"));payments.put(UUID.fromString(key),new Payment(attempt,protocol,terms));}
  if(y.contains("reputation-outbox")&&!y.isList("reputation-outbox")||y.contains("audit-outbox")&&!y.isList("audit-outbox"))throw new IOException("Повреждён исходящий журнал договоров");var reputation=new LinkedHashMap<String,ReputationOutcome>();for(var row:y.getMapList("reputation-outbox")){var value=new ReputationOutcome((String)row.get("id"),(String)row.get("scope"),UUID.fromString((String)row.get("subject")),(String)row.get("rule"),new java.math.BigDecimal(String.valueOf(row.get("at"))).longValueExact(),(String)row.get("context"));if(reputation.put(value.id(),value)!=null)throw new IOException("Повтор репутационного события");}
  var audit=new ArrayList<AuditRecord>();for(Object row:y.getList("audit-outbox",List.of())){if(!(row instanceof List<?> fields)||fields.stream().anyMatch(value->!(value instanceof String)))throw new IOException("Повреждён журнал поставки");audit.add(AuditRecord.parse(fields.stream().map(String.class::cast).toList()));}data.loaded(new Image(contracts,actors,payments,reputation,audit));
 }
 private static long integer(ConfigurationSection section,String key){return new java.math.BigDecimal(String.valueOf(section.get(key))).longValueExact();}
 public CompletionStage<Image> commit(Image before,Image next){return data.commit(before,next);}
 public CompletionStage<SupplyContract> put(SupplyContract c,UUID actor,Payment payment,boolean clearPayment,Collection<ReputationOutcome> outcomes,AuditRecord record){try(var guard=SuiteState.guard()){
  var old=image();var rows=new LinkedHashMap<>(old.contracts());rows.put(c.terms().id(),c);var actors=new HashMap<>(old.actors());var closed=rows.values().stream().filter(value->!value.open()).sorted(Comparator.comparingLong((SupplyContract value)->value.terms().created()).reversed()).toList();if(closed.size()>1000)closed.subList(1000,closed.size()).forEach(value->rows.remove(value.terms().id()));actors.keySet().retainAll(rows.keySet());if(actor!=null){UUID prior=actors.putIfAbsent(c.terms().id(),actor);if(prior!=null&&!prior.equals(actor))throw new IllegalArgumentException("Инициатор согласия по договору уже сохранён");}var payments=new HashMap<>(old.payments());if(clearPayment)payments.remove(c.terms().id());if(payment!=null)payments.put(c.terms().id(),payment);var reputation=new LinkedHashMap<>(old.reputation());for(var outcome:outcomes){var prior=reputation.putIfAbsent(outcome.id(),outcome);if(prior!=null&&!prior.equals(outcome))throw new IllegalArgumentException("Конфликт репутационного события");}var audit=new ArrayList<>(old.audit());if(record!=null){var prior=audit.stream().filter(r->r.id().equals(record.id())).findFirst().orElse(null);if(prior==null)audit.add(record);else if(!prior.identity().equals(record.identity()))throw new IllegalArgumentException("Конфликт квитанции поставки");}return commit(old,new Image(rows,actors,payments,reputation,audit)).thenApply(ack->c);
 }}
 public CompletionStage<Void> auditAck(String id){try(var guard=SuiteState.guard()){var old=image();var next=old.audit().stream().filter(r->!r.id().equals(id)).toList();return commit(old,new Image(old.contracts(),old.actors(),old.payments(),old.reputation(),next)).thenApply(v->null);}}
 public CompletionStage<Void> reputationAck(String id){try(var guard=SuiteState.guard()){var old=image();var next=new LinkedHashMap<>(old.reputation());next.remove(id);return commit(old,new Image(old.contracts(),old.actors(),old.payments(),next,old.audit())).thenApply(v->null);}}
 private static String encode(Image image){var y=new YamlConfiguration();y.set("schema",2);y.createSection("contracts");for(var c:image.contracts().values())SupplyRepository.write(y.createSection("contracts."+c.terms().id()),c);image.actors().forEach((id,actor)->y.set("actors."+id,actor.toString()));image.payments().forEach((id,p)->{String path="payments."+id+".";y.set(path+"attempt",p.attempt().toString());y.set(path+"protocol",p.protocol());if(p.terms()!=null){var t=p.terms();y.set(path+"operation",t.operation().toString());y.set(path+"town",t.town().toString());y.set(path+"actor",t.actor().toString());y.set(path+"cents",t.cents());y.set(path+"category",t.category());y.set(path+"source",t.source());y.set(path+"reason",t.reason());}});y.set("reputation-outbox",image.reputation().values().stream().map(o->Map.of("id",o.id(),"scope",o.scope(),"subject",o.subject().toString(),"rule",o.rule(),"at",o.at(),"context",o.context())).toList());y.set("audit-outbox",image.audit().stream().map(AuditRecord::fields).toList());String text=y.saveToString();if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>32L*1024*1024)throw new IllegalStateException("Журнал договоров больше 32 МиБ");return text;}
}
